<?php require_once __DIR__.'/../../app/bootstrap.php';$d=body();$name=trim($d['name']??'');$email=strtolower(trim($d['email']??''));$pw=$d['password']??'';if(!$name||!filter_var($email,FILTER_VALIDATE_EMAIL)||strlen($pw)<10)respond(['error'=>'Name, valid email and 10-character password required'],422);try{$s=db()->prepare("INSERT INTO users(name,email,password_hash) VALUES(?,?,?)");$s->execute([$name,$email,password_hash($pw,PASSWORD_DEFAULT)]);respond(['success'=>true,'user_id'=>(int)db()->lastInsertId()],201);}catch(PDOException $e){respond(['error'=>'Email already exists'],409);}
